def parse_declaration_expressn_memberaccess(self, lhsAST, rhsAST, es):
        """
        Instead of "Class.variablename", use "Class.rv('variablename')".

        :param lhsAST:
        :param rhsAST:
        :param es:
        :return:
        """
        if not isinstance(rhsAST, AST.MemberAccess):
            return
        if not isinstance(rhsAST.target, AST.Identifier):
            return
        if not isinstance(rhsAST.member, AST.Identifier):
            return
        if not isinstance(lhsAST, AST.Identifier):
            return
        if not isinstance(lhsAST.name, str):
            return
        if not isinstance(rhsAST.member.name, str):
            return
        if not isinstance(rhsAST.target.name, str):
            return
        if lhsAST.name != rhsAST.target.name:
            return
        if rhsAST.member.name != 'rv':
            return
        es.append(
            ExpressionStatement(
                Expression(
                    MemberAccess(
                        MemberAccess(
                            Identifier(
                                lhsAST.name
                            ),
                            Identifier(
                                'rv'
                            )
                        ),
                        Identifier(
                            rhsAST.member.name
                        )
                    )
                )
            )
        )

